import{z as o,x as l,o as B,c as d,q as s,j as i,D as e,d as n,s as r,S as t,b as a}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"补贴的设计","description":"","frontmatter":{"title":"补贴的设计","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/env-subsidy-design.md","filePath":"econ/env-subsidy-design.md","lastUpdated":1791063341000}'),D={name:"econ/env-subsidy-design.md"};function p(m,E,h,u,f,c){const A=l("Mermaid");return B(),d("div",null,[E[2]||(E[2]=s('<h1 id="补贴的设计" tabindex="-1">补贴的设计 <a class="header-anchor" href="#补贴的设计" aria-label="Permalink to &quot;补贴的设计&quot;">​</a></h1><div class="epigraph"><p>税收要人掏钱，补贴只要财政掏钱：政治更爱后者，经济只要求它补对外部性，别把本来就会发生的事再补一遍。</p><footer>—— 据 Pigou, The Economics of Welfare, 1920 与 Weitzman, Prices vs. Quantities, 1974 整理</footer></div><p><a href="/econ/env-cbam">上一课</a>把价格侧的防泄漏补到口岸，「收钱」的楔子齐了：税、帽、边境调节都往污染方向加价。可政策实务里最常见的楔子是「发钱」：补贴让受益者看得见、让反对者有得谈。本课沿用 <a href="/econ/deadweight-loss-measure">死重损失的度量</a> 的三角形与 <a href="/econ/env-energy-transition">能源转型经济学</a> 的学习曲线，把补贴从口号还原成参数：补哪个失灵、补多少、用什么工具、何时退。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>补贴最常犯的错是一次治两个病。排放外部性应由碳价治，知识外溢应由学习政策治；若碳价缺位而用从量补贴顶上，等于在错误的边上楔入：每单位清洁产出都拿钱，边际内项目——没有补贴也会建的项目——一起领赏，财政成本按总装机而非增量计，被系统性低估。更隐蔽的是帽子给定时的错觉：总排放钉在帽上，补贴压低许可需求，许可价随之下跌，未受补贴的行业反而减得更少——总量一吨没少。缺口因此是：给补贴找到它真正治的失灵，以及一个写下来就不许赖掉的退出时间表。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>参数化：从量补贴 \\(s\\) 把清洁技术的私人成本压低 \\(s\\)，其社会价值来自两处——碳价缺位时的边际损害项，加上学习外溢的动态项（装机翻倍带来的成本下降被未来所有项目共享）；碳价已在时第一项归零，补贴只剩学习理由。工具族按「补什么」分：按装机补（投资补贴）、按发电量补（生产抵免或固定上网电价）、差价合约（行权价双向结算：市价高于行权价时企业退钱）、拍卖分配（让竞争报出真实成本）。四条设计纪律：拍卖定成本，结算双向对称，退坡写进规则——随累计装机走、不随预算年走，只补增量。</p>',7)),(B(),i(t,null,{default:e(()=>[r(A,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAIL%5B%22%E4%B8%A4%E4%B8%AA%E5%A4%B1%E7%81%B5%3A%20%E6%8E%92%E6%94%BE%E5%A4%96%E9%83%A8%E6%80%A7%20%2B%20%E7%9F%A5%E8%AF%86%E5%A4%96%E6%BA%A2%22%5D%20--%3E%20PRICE%5B%22%E7%A2%B3%E4%BB%B7%E6%B2%BB%E5%89%8D%E8%80%85%22%5D%0A%20%20FAIL%20--%3E%20SUB%5B%22%E8%A1%A5%E8%B4%B4%E6%B2%BB%E5%90%8E%E8%80%85%22%5D%0A%20%20CAP%5B%22%E5%B8%BD%E5%AD%90%E7%BB%99%E5%AE%9A%22%5D%20--%3E%20TRAP%5B%22%E8%A1%A5%E8%B4%B4%E5%8E%8B%E8%AE%B8%E5%8F%AF%E4%BB%B7%3A%20%E6%80%BB%E9%87%8F%E4%B8%8D%E5%8F%98%22%5D%0A%20%20SUB%20--%3E%20TOOLS%5B%22%E6%8B%8D%E5%8D%96%20%2B%20%E5%8F%8C%E5%90%91%E5%B7%AE%E4%BB%B7%20%2B%20%E8%A7%84%E5%88%99%E5%8C%96%E9%80%80%E5%9D%A1%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"「差价合约」（CfD）翻译成大白话：企业和政府事先约定一个「行权价」，市价低于它时财政补差价，市价高于它时企业把多赚的退回来——双向结算等于给投资者一张稳收入的保险单，同时把超额横财还给财政。")],-1)),E[4]||(E[4]=a("p",null,[a("span",{class:"marginnote"},"「只补增量」为什么值钱：假设一年新建 10 吉瓦风电，其中 8 吉瓦没有补贴也会建；若按总装机每吉瓦补 5 亿元，财政花 50 亿元买到的真实增量只有 2 吉瓦——每吉瓦增量的真实成本是 25 亿元，是名义补贴的 5 倍。")],-1)),E[5]||(E[5]=a("h2",{id:"机制",tabindex:"-1"},[n("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[6]||(E[6]=a("p",null,"帽子给定为什么补贴不减总量：配额市场均衡要求许可价等于边际减排成本，被补贴部门少要配额，价格下落，其余部门把省下的配额用掉——负担重排，帽子未动；绿色部门拿到份额，最脏的免费配额行业反而扩张，这条机制有正式论证（Böhringer 与 Rosendahl 2010）。退坡为什么必须规则化：退坡是补贴的政治逆过程，指望预算年届时的立法自觉，等于指望帽子自我收紧——上一课 MSR 的同一招：把「怎样动」预先写进规则，预期才不崩。双向差价为什么优于单向：对称结算把超额收益还给财政与消费者，市价高企时不必临时加钱，横财与兜底一起治。",-1)),(B(),i(t,null,{default:e(()=>[r(A,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUB%5B%22%E7%BB%99%E6%B8%85%E6%B4%81%E9%83%A8%E9%97%A8%E5%8F%91%E4%BB%8E%E9%87%8F%E8%A1%A5%E8%B4%B4%22%5D%20--%3E%20LESS%5B%22%E6%B8%85%E6%B4%81%E9%83%A8%E9%97%A8%E5%87%8F%E6%8E%92%E5%B9%B6%E5%B0%91%E8%A6%81%E9%85%8D%E9%A2%9D%22%5D%0A%20%20LESS%20--%3E%20DOWN%5B%22%E9%85%8D%E9%A2%9D%E5%B8%82%E5%9C%BA%E9%9C%80%E6%B1%82%E4%B8%8B%E9%99%8D%22%5D%0A%20%20DOWN%20--%3E%20LOWP%5B%22%E8%AE%B8%E5%8F%AF%E4%BB%B7%E6%A0%BC%E4%B8%8B%E8%B7%8C%22%5D%0A%20%20LOWP%20--%3E%20BUY%5B%22%E5%85%B6%E4%BD%99%E9%83%A8%E9%97%A8%E4%BD%8E%E4%BB%B7%E5%A4%9A%E4%B9%B0%E9%85%8D%E9%A2%9D%22%5D%0A%20%20BUY%20--%3E%20EXPAND%5B%22%E5%85%8D%E8%B4%B9%E9%85%8D%E9%A2%9D%E7%9A%84%E8%84%8F%E8%A1%8C%E4%B8%9A%E5%8F%8D%E8%80%8C%E6%89%A9%E5%BC%A0%22%5D%0A%20%20DOWN%20--%3E%20CAPN%5B%22%E5%B8%BD%E5%AD%90%E6%9C%AA%E5%8A%A8%3A%20%E6%80%BB%E6%8E%92%E6%94%BE%E4%B8%80%E5%90%A8%E6%B2%A1%E5%B0%91%22%5D%0A%20%20LOWP%20--%3E%20VERDICT%5B%22%E8%A1%A5%E8%B4%B4%E9%87%8D%E6%8E%92%E4%BA%86%E8%B4%9F%E6%8B%85%2C%20%E6%B2%A1%E6%9C%89%E5%87%8F%E6%8E%92%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=s('<p><span class="marginnote">初学者容易以为「补了清洁能源 = 排放就少了」。在排放帽下，帽子的吨数才是排放总量的唯一决定者：补贴改变的只是「谁用掉这些吨位」。想让补贴产生真减排，要么先有碳价，要么同步收紧帽子。</span></p><p><span class="marginnote">英国海上风电差价合约：早期轮次出清价约 110—120 英镑/MWh，2022 年轮次约 37 英镑/MWh（2012 年不变价）——拍卖加双向结算同时完成成本发现与横财回收。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>补贴占住财政与注意力，错误的补贴比没有补贴更贵。退坡常被投资者当作违约，规则化只降低、不消除这一风险。上游材料瓶颈会把补贴转成供应商租金；跨境的补贴摩擦会引来反补贴税——与上一课的边境机制在同一张桌子上相遇。补贴不是碳价的替代品：两个失灵各配一个工具，缺谁谁失灵；把补贴当万能钥匙的政治惯性，是这门课要对抗的第一直觉。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>补贴要指名它治的失灵：顶替碳价是在错误的边上楔入，边际内横财被系统性漏算。</li><li>帽子给定时不减总量：许可价下跌、负担重排，只有帽子收紧才谈得上额外减排。</li><li>工具族按「补什么」选：装机、发电量、差价、拍卖各有信息与横财含义。</li><li>四条纪律：拍卖定成本、双向结算、退坡随累计装机规则化、只补增量。</li><li>出处：Pigou 1920；Böhringer &amp; Rosendahl 2010；英国 CfD 数据据官方轮次口径。</li></ul>',6))])}const _=o(D,[["render",p]]);export{P as __pageData,_ as default};
